#[test]
fn debug_tree() {
    for src in [
        "x = [1 2 3];\n",
        "c = {1 2};\n",
        "function f()\nfor i = 1:10\nx = i;\nend\nend\n",
        "if (x > 0)\n    y = 1;\nend\n",
        "disp('hello');\n",
        "foo(a b);\n",
    ] {
        println!("===== SRC: {src:?} =====");
        let tree = parse(src);
        fn walk(node: tree_sitter::Node, src: &str, depth: usize) {
            let text: String = src[node.byte_range()]
                .chars()
                .filter(|c| !c.is_control())
                .collect();
            println!("{}{} [{}-{}] {:?}", "  ".repeat(depth), node.kind(), node.start_byte(), node.end_byte(), text);
            let mut c = node.walk();
            for ch in node.children(&mut c) {
                walk(ch, src, depth + 1);
            }
        }
        walk(tree.root_node(), src, 0);
    }
    panic!("debug");
}

