import re
# Language spec targets from PLAN.md 3.8a-d
parfor = """PFANSLP PFANSNS PFFORA PFGLOB PFINPT PFPERS PFCTXT PFFRNG PFMLTI PFANON PFFSUB PFINCR PFVARS PFVSUB PFRNG PFPF PFSPMD PFBRK PFRTN PFLD PFSV PFNAR PFUTVR PFUTMP PFEVC PFNAIO PFNACK PFSLO PFSLW PFSLRD PFUNK PFNF PFRFH PFXST PFCEL BRKFOR CONTFOR FWFORP FPFORP""".split()
class_ = """MCDIR MCFIL MCEB MCSGP MCSGA MCS2I MCS1O MCG1I MCG1O MCGSA MCSCN MCANI MCASC MCRED MCCBD MCPSG MCSCT MCSCO MCSCF MCCBS MCCBU MCCMC MCSCC MCSCM MCCSOP MTMAT MTAGS3 MCAPP MABSEAC MABSEAM MCMIO MCMSP MCMTP MHERIT MCSWA MCPIN MWKREF MWKCT MWKCL MCSMO""".split()
funcval = """FVAPN FVATF FVIOA FVBTN FVDAN FVDAP FVDNF FVDREP FVMCL FVNDE FVIDV FVNIV FVNREP FVOND FVORDI FVORDN FVORDO FVORDP FVONV FVREPD FVREPO FVNSC FVNVL FVSOR FVSORO FVUBD FVVCON FVOCON FVVIN FVVREP TTOOFEWDIMS TINVALDIM FVOBI FVOOD FVOON FVOVREP FVOOI FVORM""".split()
other = """FCONV FCONF ROWLN GPFST GPNES NPERS SPDEC SPDEC3 SPNST SPRET SPBRK SPLD SPSV SPGP SPEVC SPBFN SPNF SPWHOS FCNANS CLANS USESWNS IDXCOLND CTOINE CTORO NCHKOS ERTXT WTXT""".split()
target = set(parfor+class_+funcval+other)
impl = set("""BRKFOR CLANS CONTFOR FCNANS FCONF FCONV FVNST GPFST GPNES IDXCOLND MCANI MCASC MCCBD MCDIR MCEB MCFIL MCG1I MCG1O MCRED MCS1O MCS2I MCSGA MCSGP NPERS PFBRK PFFORA PFGLOB PFNF PFPERS PFPF PFRTN PFSPMD PFXST ROWLN SPGP SPNST SPRET""".split())
missing = sorted(target - impl)
print("langspec total:", len(target), "implemented:", len(target & impl), "missing:", len(missing))
import collections
def group(ids):
    g = collections.defaultdict(list)
    for i in ids:
        if i.startswith("PF") or i in ("BRKFOR","CONTFOR","FWFORP","FPFORP"): g["parfor"].append(i)
        elif i.startswith("MC") or i.startswith("AT") or i.startswith("MCS") or i.startswith("MW") or i.startswith("MT") or i.startswith("MA"): g["class"].append(i)
        elif i.startswith("FV") or i.startswith("TT") or i.startswith("TINV"): g["funcval"].append(i)
        else: g["other"].append(i)
    return g
for k,v in group(missing).items():
    print(k, len(v), v)
EOF

