def find_method_end(start_idx):
    """Given index of line containing 'fn name(', find the end line of the method body (balanced braces)."""
    # accumulate from the line with the signature through its body
    depth = 0
    started = False
    i = start_idx
    while i < len(lines):
        line = lines[i]
        for ch in line:
            if ch == '{':
                depth += 1
                started = True
            elif ch == '}':
                depth -= 1
                if started and depth == 0:
                    return i
        i += 1
    raise RuntimeError(f"no end for method starting at line {start_idx}")

# Map: method name -> (start_line, end_line)
methods = {}
# patterns: '    fn check_xxx(' or '    fn walk_xxx('
