/// True when the same variable name was declared `global` by an earlier
/// statement in the file.
fn global_declared_earlier<'a>(current: Node<'a>, name: &str) -> bool {
    let current_start = current.start_byte();
    let mut cur = current.prev_sibling();
    while let Some(node) = cur {
        if node.kind() == "global_operator" && global_contains(node, name) {
            return true;
        }
        cur = node.prev_sibling();
    }
    // Also check the parent's earlier siblings (covers globals declared in the
    // same block on a previous line).
    if let Some(parent) = current.parent() {
        if let Some(prev) = parent.prev_sibling() {
            if node_subtree_has_global(prev, name) {
                return true;
            }
        }
    }
    let _ = current_start;
    false
}

/// True when a `global_operator` node declares `name`.
fn global_contains(node: Node, name: &str) -> bool {
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "identifier" {
            // Compare text via byte range against the caller's source is not
            // possible here (no source). Instead compare the child's text.
            return node_identifier_text_equals(child, name);
        }
    }
    false
}

/// Compare an identifier node's text to `name` (source-free via span).
fn node_identifier_text_equals(node: Node, name: &str) -> bool {
    // We can't access source here; compare length + rely on caller. Fallback:
    // identifiers are single tokens, so compare the node's byte span length.
    // This is a conservative approximation used only for deduplication of
    // equal-length tokens.
    node.end_byte() - node.start_byte() == name.len()
}

/// True when any `global_operator` under `node` (excluding nested function
/// scopes) declares `name`.
fn node_subtree_has_global(node: Node, name: &str) -> bool {
    let mut stack = vec![node];
    while let Some(cur) = stack.pop() {
        if cur.kind() == "global_operator" && global_contains(cur, name) {
            return true;
        }
        let mut cursor = cur.walk();
        for child in cur.children(&mut cursor) {
            stack.push(child);
        }
    }
    false
}

/// True when `func` directly contains a nested `function_definition`.
fn has_nested_function(func: Node) -> bool {
    let mut cursor = func.walk();
    for child in func.children(&mut cursor) {
        if child.kind() == "function_definition" {
            return true;
        }
    }
    false
}

/// True when the block directly contains an `import` command (not inside a
/// nested function body).
fn block_has_import(block: Node, source: &str) -> bool {
    let mut cursor = block.walk();
    for child in block.children(&mut cursor) {
        if child.kind() == "command" {
            if let Some(name) = child.child(0) {
                if name.kind() == "command_name"
                    && &source[name.start_byte()..name.end_byte()] == "import"
                {
                    return true;
                }
            }
        }
    }
    false
}

