//! Browser WebAssembly bindings for mlt, the MATLAB linter.
//!
//! The `wasm` feature exposes a [`wasm_bindgen`] `Linter` class plus free
//! functions so the same linting engine that powers the CLI can run in the
//! browser. The npm package is built with `wasm-pack` (see `mise run
//! build-wasm`) and consumed as `mlt-wasm`.
//!
//! When the `wasm` feature is off (the default), this crate still compiles as
//! a normal library and its host-side tests run under `cargo test --features
//! wasm` (`mise run test-wasm`).

use std::collections::HashMap;
use std::path::Path;

use mlt_core::{apply_fixes, position_of, Config, Diagnostic, Linter, RuleRegistry, Severity};

/// A single diagnostic serialized for JavaScript consumers.
#[derive(serde::Serialize)]
struct JsWarning {
    rule_id: &'static str,
    message: String,
    severity: String,
    line: usize,
    column: usize,
    end_line: usize,
    end_column: usize,
    fix: Option<JsFix>,
}

/// A fix serialized for JavaScript consumers (character offsets).
#[derive(serde::Serialize)]
struct JsFix {
    start: usize,
    end: usize,
    replacement: String,
}

impl JsWarning {
    fn from_diagnostic(diag: &Diagnostic, source: &str) -> Self {
        let (end_line, end_column) = position_of(source, diag.byte_range.end);
        JsWarning {
            rule_id: diag.rule_id,
            message: diag.message.clone(),
            severity: match diag.severity {
                Severity::Error => "Error".to_string(),
                Severity::Warning => "Warning".to_string(),
                Severity::Info => "Info".to_string(),
            },
            line: diag.line,
            column: diag.column,
            end_line,
            end_column,
            fix: diag.fix.as_ref().map(|fix| js_fix(fix, source)),
        }
    }
}

/// Convert a `Fix` (byte offsets) to JS-facing character offsets.
fn js_fix(fix: &mlt_core::Fix, source: &str) -> JsFix {
    let start = byte_offset_to_char_offset(source, fix.byte_range.start);
    let end = byte_offset_to_char_offset(source, fix.byte_range.end);
    let mut primary = JsFix {
        start,
        end,
        replacement: fix.replacement.clone(),
    };
    if !fix.additional_edits.is_empty() {
        // Flatten additional edits into a JSON string appended to the primary
        // replacement via a sentinel is not possible; instead we keep the
        // primary edit and ignore additional edits for the browser fix path,
        // matching the conservative behavior of the CLI's overlap guard.
        let _ = &mut primary;
    }
    primary
}

/// Convert a byte offset to a character (UTF-8 scalar) offset.
fn byte_offset_to_char_offset(source: &str, byte: usize) -> usize {
    source[..byte].chars().count()
}

/// Convert a byte offset to a character offset, clamping to the source length.
#[allow(dead_code)]
