/** Naming engine check IDs: `naming.<entity>.<checkType>` Cartesian product. */
function namingChecks(): Array<[string, string]> {
  const entities = [
    'class',
    'function',
    'localFunction',
    'method',
    'nestedFunction',
    'property',
    'event',
    'enumeration',
    'variable',
  ]
  const checkTypes = [
    'maxLength',
    'minLength',
    'regularExpression',
    'requiredPrefix',
    'disallowedPrefix',
    'disallowedPhrase',
    'requiredSuffix',
    'disallowedSuffix',
    'casing',
  ]
  const out: Array<[string, string]> = []
