import { readFileSync } from 'node:fs'
function moduleDocstring(file: string): string {
  const lines = readFileSync(file, 'utf8').split('\n')
  const out: string[] = []
  for (const ln of lines) {
    const m = ln.match(/^\s*\/\/!(.*)$/)
    if (!m) break
    out.push(m[1].replace(/^ /, ''))
  }
  return out.join('\n')
}
function parseFrontMatter(doc: string) {
  const lines = doc.split('\n')
  let i = lines.findIndex((l) => l.trim() === '```mlt')
  if (i === -1) return null
  const kv: Record<string, string> = {}
  for (let j = i + 1; j < lines.length; j++) {
    const l = lines[j].trim()
    if (l === '```') break
    const m = l.match(/^([A-Za-z_]+)\s*=\s*(.+)$/)
    if (!m) continue
    let v = m[2].trim()
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1)
    kv[m[1]] = v
  }
  if (!kv.id) return null
  return { ...kv, id: kv.id, fix: (kv.fix ?? 'false') === 'true', severity: kv.severity ?? 'warning' }
}
